def gen(rng):
    def fmt(k, a):
        return f'{len(a)} {k}\n' + ' '.join(map(str, a))
    tests = [fmt(1, [5]), fmt(1, [3, 9, 2]), fmt(3, [4, 4, 4]), fmt(2, [1, 5, 3, 4, 2]), fmt(3, [150, 200, 400, 350, 250]),
             fmt(4, [9, 2, 7, 3]), fmt(2, [10**5, 1]), fmt(2, [1, 10**5]), fmt(3, [5, 4, 3, 2, 1]), fmt(3, [1, 2, 3, 4, 5])]
    for n in (2, 3, 4, 5, 6, 8, 10, 12):
        for _ in range(3):
            k = rng.randint(1, n)
            tests.append(fmt(k, [rng.randint(1, rng.choice([5, 20, 100])) for _ in range(n)]))
    N = 300
    tests.append(fmt(150, [rng.randint(1, 10**5) for _ in range(N)]))
    tests.append(fmt(100, [rng.randint(1, 10**5) for _ in range(N)]))
    tests.append(fmt(N, [rng.randint(1, 10**5) for _ in range(N)]))
    tests.append(fmt(7, sorted(rng.randint(1, 10**5) for _ in range(N))))
    tests.append(fmt(200, sorted((rng.randint(1, 10**5) for _ in range(N)), reverse=True)))
    return tests

